# WAR ARENA - Channel Membership Gate - Installer
# Requires Telegram channel membership for operations (scan/monitor).
# Browsing stays open. Set REQUIRED_CHANNEL in env; bot must be channel admin.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-membership.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Channel membership gate installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/legal/membershipGate.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "src/api/wiredApp.ts" ""
Write-B64 "src/deploy/env.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "tests/unit/membershipGate.test.ts" ""
Write-B64 "tests/integration/wiredApi.test.ts" ""
Write-B64 ".env.example" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Membership gate installed. Expected: 1017 passed + 1 skipped, 475 guards." -ForegroundColor Green
Write-Host "Set REQUIRED_CHANNEL=@YourChannel in .env; make the bot a channel admin." -ForegroundColor Yellow
